71: void translate_block(CXXWriter& out, ast::Block block)
72: {
73: 	for (auto&& s : block)
74: 	{
75: 		if (s.is<ast::FuncDecl>())
76: 		{
77: 			// TODO support param deconstruction
78: 
79: 			auto&& f = s.get<ast::FuncDecl>();
80: 
81: 			auto&& auto_params = vector<string>{};
82: 			for (auto&& param : f.params)
83: 			{
84: 				if (!param.pat.type)
