86: 			}
87: 
88: 			if (auto_params.size())
89: 				out.write("template <typename T" + str::join(", typename T", auto_params) + ">");
90: 
91: 			auto&& cxx = string{};
92: 			cxx += "inline auto " + f.name + "(";
93: 			bool first = true;
94: 			for (auto&& param : f.params)
95: 			{
96: 				if (first)
97: 					first = false;
98: 				else
99: 					cxx += ", ";
100: 
101: 				if (param.pat.type)
102: 					cxx += translate_expr(*param.pat.type);
103: 				else
104: 					cxx += "T" + param.pat.pat.get<ast::PatIdent>().name + "&&";
105: 				cxx += " " + param.pat.pat.get<ast::PatIdent>().name;
106: 
107: 				if (param.default_value)
108: 					cxx += " = " + translate_expr(*param.default_value);
109: 			}
110: 			cxx += ")";
111: 
112: 			if (f.return_type)
113: 				cxx += " -> " + translate_expr(*f.return_type);
114: 
115: 			if (!auto_params.size() && f.return_type)
116: 			{
117: 				// This function is fully specified!
118: 				// We can hide it in the .cpp file.
119: 			}
120: 
121: 			out.write(cxx);
122: 
123: 			out.begin();
124: 			if (f.code)
125: 				translate_block(out, *f.code);
126: 			out.end();
127: 		}
128: 		else if (s.is<ast::LetDecl>())
129: 		{
130: 			auto&& l = s.get<ast::LetDecl>();
131: 
132: 			assert(l.value); // TODO handle value-less lets
133: 
134: 			if (l.pat.pat.is<ast::PatTuple>())
135: 			{
136: 				// Convert
137: 				// let (a, b, c) = (1, 2, 3)
138: 				// to
139: 				// auto&& temp = (1, 2, 3)
140: 				// auto&& a = std::get<0>(temp);
141: 				// auto&& b = std::get<1>(temp);
142: 				// auto&& c = std::get<2>(temp);
143: 			}
144: 
145: 			auto&& pat = l.pat.pat.get<ast::PatIdent>();
146: 
147: 			auto&& cxx = string{};
148: 			cxx += "auto&& " + pat.name + " = ";
149: 			if (!pat.is_mutable)
150: 				cxx += "pycxx_runtime::freeze(";
151: 			if (l.pat.type)
152: 				cxx += translate_expr(*l.pat.type) + "{";
153: 			cxx += translate_expr(*l.value);
154: 			if (l.pat.type)
155: 				cxx += "}";
156: 			if (!pat.is_mutable)
157: 				cxx += ")";
158: 
159: 			out.write(cxx + ";");
160: 		}
161: 		else if (s.is<ast::Loop>())
162: 		{
163: 			auto&& l = s.get<ast::Loop>();
164: 
165: 			out.write("for (;;)");
166: 			out.begin();
167: 			if (l.code)
168: 				translate_block(out, *l.code);
169: 			out.end();
170: 		}
171: 		else if (s.is<ast::ForLoop>())
172: 		{
173: 			auto&& l = s.get<ast::ForLoop>();
174: 
175: 			if (l.pat.pat.is<ast::PatTuple>())
176: 			{
177: 				// TODO
178: 			}
179: 
180: 			auto&& pat = l.pat.pat.get<ast::PatIdent>();
181: 
182: 			out.write("for (auto&& " + pat.name + " : " + translate_expr(l.expr) + ")");
183: 
184: 			out.begin();
185: 			if (l.code)
186: 				translate_block(out, *l.code);
187: 			out.end();
188: 		}
189: 		else if (s.is<ast::ExprStatement>())
190: 		{
191: 			auto&& expr = s.get<ast::ExprStatement>().expr;
192: 
193: 			out.write(translate_expr(expr) + ";");
194: 		}
195: 	}
